class Solution {
public:
    int maximalPathQuality(vector<int>& values, vector<vector<int>>& edges, int maxTime) {
        int n = values.size();
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }

        vector<int> dist(n, INT_MAX);
        dist[0] = 0;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }

        vector<int> visited(n, 0);
        long long ans = 0;
        long long curQ = values[0];
        visited[0] = 1;

        function<void(int,int)> dfs = [&](int u, int time) {
            if (u == 0) {
                ans = max(ans, curQ);
            }
            for (auto& [v, w] : adj[u]) {
                if (dist[v] == INT_MAX) continue;
                if (time + w + dist[v] > maxTime) continue;
                bool added = false;
                if (visited[v] == 0) {
                    curQ += values[v];
                    added = true;
                }
                visited[v]++;
                dfs(v, time + w);
                visited[v]--;
                if (added) curQ -= values[v];
            }
        };

        dfs(0, 0);
        return (int)ans;
    }
};
